  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "reference_class anchored on the growth trajectory of English Wikipedia article counts, as tracked by Wikimedia Foundation analytics; the anchor reflects the baseline expectation from late-2025 figures (~7M English articles) and historical growth pace."
