    "factor_updates": [
      {
        "factor": "Near-term growth pace of English Wikipedia articles",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "With late-2025 counts around 7,000,000 and growth rates of hundreds of new articles per day, crossing the remaining ~1,007 articles in the days ahead is plausible."
      },
      {
        "factor": "Milestone momentum from the 25th anniversary and sustained engagement",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": " Anniversary campaigns and ongoing Year in Review metrics indicate continuing engagement and content-generation momentum that support further growth."
